const itens = Array.isArray($json) ? $json : [];
const restaurante = $('Extrair Restaurante').item.json.restaurante;
if (itens.length === 0) {
  return [{ json: { texto: `O cardápio de *${restaurante.nome}* está vazio no momento.`, itens: [] } }];
}
const lista = itens.slice(0, 8).map((item, i) => `*${i+1}.* ${item.nome} - R$ ${parseFloat(item.preco || 0).toFixed(2)}${item.descricao ? '\n   _' + item.descricao + '_' : ''}`).join('\n');
// Cross-sell: pega um item aleatório como sugestão complementar
const sugestao = itens.find(i => i.categoria === 'bebida' || i.categoria === 'sobremesa');
const crossSell = sugestao ? `\n\n💡 *Sugestão:* ${sugestao.nome} (R$ ${parseFloat(sugestao.preco || 0).toFixed(2)}) combina muito!` : '';
return [{ json: { texto: `🍽️ Cardápio de *${restaurante.nome}*:\n\n${lista}${crossSell}\n\nO que deseja pedir? (pode escrever o nome ou o número)`, itens } }];

