parameters.jsCode:
const resp = $json;
let itens = [];
try {
  itens = JSON.parse(resp.content?.[0]?.text?.trim() || '[]');
} catch(e) { itens = []; }
const restaurante = $('Detectar Etapa').item.json.contexto.restaurante || {};
const subtotal = itens.reduce((s, i) => s + (parseFloat(i.preco || 0) * (i.quantidade || 1)), 0);
const taxa_entrega = parseFloat(restaurante.taxa_entrega || 0);
const total = subtotal + taxa_entrega;
const resumo = itens.map(i => `${i.quantidade || 1}x ${i.nome} - R$ ${(parseFloat(i.preco || 0) * (i.quantidade || 1)).toFixed(2)}`).join('\n');
return [{ json: { itens, subtotal, taxa_entrega, total, resumo } }];

